"><h3 class=\"m-text-6\">04</h3><p class=\"m-text-5\">Go live</p><p class=\"m-text\">We complete final checks and launch once the agreed scope is ready.</p><div class=\"wk-photo\"><svg aria-label=\"Illustration of go live in the website project process\" class=\"process-scene\" data-process-demo=\"go-live\" role=\"img\" viewBox=\"0 0 600 380\"><defs><clippath id=\"process-clip-go-live\"><rect height=\"354\" rx=\"13\" width=\"574\" x=\"13\" y=\"13\"></rect></clippath></defs><g clip-path=\"url(#process-clip-go-live)\"><rect fill=\"#111214\" height=\"354\" rx=\"13\" stroke=\"#393c43\" width=\"574\" x=\"13\" y=\"13\"></rect><rect fill=\"#1d1f23\" height=\"38\" rx=\"6.08\" width=\"574\" x=\"13\" y=\"13\"></rect><g fill=\"#676d77\"><circle cx=\"33\" cy=\"32\" fill=\"#58d5e3\" r=\"4\"></circle><circle cx=\"48\" cy=\"32\" fill=\"#e8b77e\" r=\"4\"></circle><circle cx=\"63\" cy=\"32\" fill=\"#36bda9\" r=\"4\"></circle></g><text fill=\"#c8cdd5\" font-size=\"14\" x=\"87\" y=\"37\">Release checklist</text><rect fill=\"#1c2128\" height=\"253\" rx=\"12\" stroke=\"#424b58\" width=\"512\" x=\"44\" y=\"77\"></rect><circle cx=\"300\" cy=\"123\" fill=\"#254e47\" r=\"22\"></circle><path class=\"proc-check proc-moving\" d=\"m289 123 8 8 15-18\" fill=\"none\" pathLength=\"1\" stroke=\"#9ddfcd\" stroke-width=\"3\"></path><text fill=\"#e0e7ef\" font-size=\"21\" font-weight=\"600\" x=\"211\" y=\"171\">Ready for launch</text><rect fill=\"#363e49\" height=\"11\" rx=\"5\" width=\"436\" x=\"82\" y=\"194\"></rect><rect class=\"proc-progress proc-moving\" fill=\"#58d5e3\" height=\"11\" rx=\"5\" width=\"436\" x=\"82\" y=\"194\"></rect><g class=\"proc-badge proc-moving\" style=\"--i:0\"><rect fill=\"#263e3b\" height=\"41\" rx=\"8\" stroke=\"#48635d\" width=\"128\" x=\"84\" y=\"234\"></rect><path d=\"m97 254 5 5 9-11\" fill=\"none\" stroke=\"#9ddfcd\" stroke-width=\"2\"></path><text fill=\"#c4dcd6\" font-size=\"14\" x=\"123\" y=\"260\">Content</text></g><g class=\"proc-badge proc-moving\" style=\"--i:1\"><rect fill=\"#263e3b\" height=\"41\" rx=\"8\" stroke=\"#48635d\" width=\"128\" x=\"236\" y=\"234\"></rect><path d=\"m249 254 5 5 9-11\" fill=\"none\" stroke=\"#9ddfcd\" stroke-width=\"2\"></path><text fill=\"#c4dcd6\" font-size=\"14\" x=\"275\" y=\"260\">Links</text></g><g class=\"proc-badge proc-moving\" style=\"--i:2\"><rect fill=\"#263e3b\" height=\"41\" rx=\"8\" stroke=\"#48635d\" width=\"128\" x=\"388\" y=\"234\"></rect><path d=\"m401 254 5 5 9-11\" fill=\"none\" stroke=\"#9ddfcd\" stroke-width=\"2\"></path><text fill=\"#c4dcd6\" font-size=\"14\" x=\"427\" y=\"260\">Launch</text></g><path d=\"M84 301h293\" stroke=\"#5f6c7c\" stroke-width=\"5\"></path><path class=\"proc-send proc-moving\" d=\"m475 298 34-14-12 35-8-12-14-9Zm14 9 20-23\" fill=\"#58d5e3\" stroke=\"#b9d3da\" stroke-width=\"1.5\"></path></g></svg></div></li>\n<li class=\"wk-day wk-day--rest m-slide\" data-process-card=\"support\"><h3 class=\"m-text-6\">05</h3><p class=\"m-text-5\">Support after launch</p><p class=\"m-text\">Post-launch support lasts 30, 45 or 60 days depending on the selected package.</p><div class=\"wk-photo\"><svg aria-label=\"Illustration of support in the website project process\" class=\"process-scene\" data-process-demo=\"support\" role=\"img\" viewBox=\"0 0 600 380\"><defs><clippath id=\"process-clip-support\"><rect height=\"354\" rx=\"13\" width=\"574\" x=\"13\" y=\"13\"></rect></clippath></defs><g clip-path=\"url(#process-clip-support)\"><rect fill=\"#111214\" height=\"354\" rx=\"13\" stroke=\"#393c43\" width=\"574\" x=\"13\" y=\"13\"></rect><rect fill=\"#1d1f23\" height=\"38\" rx=\"6.08\" width=\"574\" x=\"13\" y=\"13\"></rect><g fill=\"#676d77\"><circle cx=\"33\" cy=\"32\" fill=\"#58d5e3\" r=\"4\"></circle><circle cx=\"48\" cy=\"32\" fill=\"#e8b77e\" r=\"4\"></circle><circle cx=\"63\" cy=\"32\" fill=\"#36bda9\" r=\"4\"></circle></g><text fill=\"#c8cdd5\" font-size=\"14\" x=\"87\" y=\"37\">Post-launch support</text><rect fill=\"#191d23\" height=\"316\" rx=\"10\" width=\"48\" x=\"13\" y=\"51\"></rect><g fill=\"#667587\"><rect height=\"17\" rx=\"4\" width=\"17\" x=\"28\" y=\"76\"></rect><rect height=\"17\" rx=\"4\" width=\"17\" x=\"28\" y=\"114\"></rect><rect height=\"17\" rx=\"4\" width=\"17\" x=\"28\" y=\"152\"></rect></g><rect fill=\"#1a242d\" height=\"133\" rx=\"10\" stroke=\"#344753\" width=\"239\" x=\"79\" y=\"72\"></rect><text fill=\"#c4d3e0\" font-size=\"14\" x=\"96\" y=\"98\">Website activity</text><path d=\"M99 177h200M99 148h200\" stroke=\"#303e4a\"></path><path class=\"proc-draw proc-moving\" d=\"m99 173 27-17 31 8 28-32 27 8 26-26 29 7 29-23\" fill=\"none\" pathLength=\"1\" stroke=\"#58d5e3\" stroke-width=\"3\"></path><rect fill=\"#1d252d\" height=\"133\" rx=\"10\" stroke=\"#3e4955\" width=\"225\" x=\"335\" y=\"72\"></rect><text fill=\"#c4d3e0\" font-size=\"14\" x=\"353\" y=\"99\">Agreed support</text><circle class=\"proc-status proc-moving\" cx=\"359\" cy=\"130\" fill=\"#65ddbd\" r=\"5\"></circle><text fill=\"#bbc9d8\" font-size=\"13\" x=\"375\" y=\"135\">Updates and questions</text><path d=\"M353 164h183M353 184h137\" stroke=\"#586777\" stroke-width=\"5\"></path><rect fill=\"#1b222a\" height=\"121\" rx=\"10\" stroke=\"#3b4855\" width=\"481\" x=\"79\" y=\"224\"></rect><path class=\"proc-check proc-moving\" d=\"m97 247 5 5 9-10\" fill=\"none\" pathLength=\"1\" stroke=\"#6bd9bb\" stroke-width=\"2\" style=\"--i:0\"></path><text fill=\"#c4d1df\" font-size=\"14\" x=\"125\" y=\"252\">Review your request</text><path d=\"M384 248h151\" stroke=\"#3c4b59\" stroke-width=\"4\"></path><path class=\"proc-check proc-moving\" d=\"m97 281 5 5 9-10\" fill=\"none\" pathLength=\"1\" stroke=\"#6bd9bb\" stroke-width=\"2\" style=\"--i:1\"></path><text fill=\"#c4d1df\" font-size=\"14\" x=\"125\" y=\"286\">Agree the next update</text><path d=\"M384 282h151\" stroke=\"#3c4b59\" stroke-width=\"4\"></path><path class=\"proc-check proc-moving\" d=\"m97 315 5 5 9-10\" fill=\"none\" pathLength=\"1\" stroke=\"#6bd9bb\" stroke-width=\"2\" style=\"--i:2\"></path><text fill=\"#c4d1df\" font-size=\"14\" x=\"125\" y=\"320\">Keep you informed</text><path d=\"M384 316h151\" stroke=\"#3c4b59\" stroke-width=\"4\"></path></g></svg></div></li>\n\n\n</ol>\n</div>\n<div aria-hidden=\"true\" class=\"wk-progress\"><span></span></div>\n</div>\n</section>\n\n<section aria-labelledby=\"stories-title\" class=\"l-sec\" data-8b-section=\"stories\" id=\"stories\">\n<div class=\"st-slide m-slide-3\">\n<h2 class=\"st-label m-text-6\" id=\"stories-title\">Know what you are choosing.</h2>\n<figure class=\"st-main\">\n<div data-8b-motion=\"streak\" data-from=\"left\"><p class=\"m-text-7\"><img alt=\"\" class=\"st-chip m-chip\" data-8b-motion=\"focus\" height=\"74\" src=\"/editorial-home/logo.webp\" width=\"108\"/>Explore the work and understand the scope before you decide.</p></div>\n<figcaption class=\"m-text-4\">Horizon Digital · Mahé, Seychelles</figcaption>\n</figure>\n<ul class=\"st-notes\" data-8b-motion=\"rise\">\n<li><p class=\"m-text\">A live client project you can visit, alongside clearly labelled concepts and demonstrations.</p><p class=\"m-text-4\">Explore our work</p></li>\n<li><p class=\"m-text\">A written scope and a clear route from first chat through launch and post-launch support.</p><p class=\"m-text-4\">Understand the process</p></li>\n</ul>\n</div>\n</section>\n\n<section aria-labelledby=\"recovery-title\" class=\"l-sec\" data-8b-section=\"recovery\" id=\"recovery\">\n<div class=\"rc-slide m-slide\">\n<div class=\"rc-text\">\n<h2 class=\"m-text-3\" id=\"recovery-title\"><span class=\"rc-row\">Support</span> <span class=\"rc-row\">beyond</span> <span class=\"rc-row brand-word\">the launch.</span></h2>\n<p class=\"m-text-5\">Your package includes a defined post-launch support window. We can scope later updates and additions around what you need.</p>\n<ul class=\"rc-list\">\n<li><strong class=\"m-text-6\">Post-launch support</strong><span class=\"m-text\">30, 45 or 60 days, depending on your package.</span></li>\n<li><strong class=\"m-text-6\">Content updates</strong><span class=\"m-text\">Editing tools for agreed fields in Starter and Growth.</span></li>\n<li><strong class=\"m-text-6\">Managed hosting</strong><span class=\"m-text\">Available as a separately priced annual service.</span></li>\n<li><strong class=\"m-text-6\">Room to grow</strong><span class=\"m-text\">Later changes can be scoped around what you need next.</span></li>\n</ul>\n</div>\n<div class=\"rc-window\"><svg aria-label=\"Illustration of reviewing a website content update within an agreed support window\" class=\"rc-care\" role=\"img\" viewBox=\"0 0 600 700\"><defs><linearGradient id=\"care-background\" x2=\"1\" y2=\"1\"><stop stop-color=\"#20434e\"></stop><stop offset=\"1\" stop-color=\"#10171c\"></stop></linearGradient><linearGradient id=\"care-image\" x2=\"1\" y2=\"1\"><stop stop-color=\"#599eac\"></stop><stop offset=\"1\" stop-color=\"#305e72\"></stop></linearGradient></defs><rect fill=\"url(#care-background)\" height=\"676\" rx=\"28\" width=\"576\" x=\"12\" y=\"12\"></rect><circle cx=\"490\" cy=\"116\" fill=\"#397a762b\" r=\"58\"></circle><rect fill=\"#111a21\" height=\"530\" rx=\"18\" stroke=\"#4a6d78\" stroke-width=\"2\" width=\"528\" x=\"36\" y=\"55\"></rect><path d=\"M37 101h526\" stroke=\"#3c5661\"></path><g><circle cx=\"59\" cy=\"79\" fill=\"#58d5e3\" r=\"5\"></circle><circle cx=\"78\" cy=\"79\" fill=\"#e8b77e\" r=\"5\"></circle><circle cx=\"97\" cy=\"79\" fill=\"#36bda9\" r=\"5\"></circle></g><text fill=\"#dbeef1\" font-size=\"17\" x=\"126\" y=\"85\">Website care</text><path d=\"M126 102v482\" stroke=\"#29414d\"></path><g fill=\"#314d5c\"><rect height=\"43\" rx=\"10\" width=\"51\" x=\"55\" y=\"127\"></rect><rect height=\"43\" rx=\"10\" width=\"51\" x=\"55\" y=\"186\"></rect><rect height=\"43\" rx=\"10\" width=\"51\" x=\"55\" y=\"245\"></rect></g><g fill=\"none\" stroke=\"#96ced7\" stroke-linejoin=\"round\" stroke-width=\"2\"><path d=\"M69 139h24v19H69Zm0 6h24M77 146v12\"></path><path d=\"M72 196h16l6 6v15H72Zm16 0v7h6M77 209h12\"></path><path d=\"M67 266h26m-23-7h20m-16 14h12\"></path></g><text fill=\"#9dc2ce\" font-size=\"15\" x=\"151\" y=\"133\">CONTENT UPDATE</text><rect fill=\"#202f39\" height=\"201\" rx=\"13\" stroke=\"#527282\" width=\"386\" x=\"150\" y=\"151\"></rect><rect fill=\"url(#care-image)\" height=\"171\" rx=\"9\" width=\"147\" x=\"163\" y=\"165\"></rect><path d=\"m164 300 42-55 29 25 42-67 33 53v80H164Z\" fill=\"#7ac6ca\"></path><circle cx=\"277\" cy=\"190\" fill=\"#e8b77e\" r=\"12\"></circle><path d=\"M330 181h181M330 203h149M330 233h172M330 252h154\" stroke=\"#c3d8df\" stroke-linecap=\"round\" stroke-width=\"6\"></path><rect fill=\"#36bda9\" height=\"29\" rx=\"8\" width=\"121\" x=\"330\" y=\"280\"></rect><g><rect fill=\"#1b2c35\" height=\"246\" rx=\"18\" stroke=\"#6cabb6\" stroke-width=\"2\" width=\"370\" x=\"182\" y=\"377\"></rect><text fill=\"#edf8f9\" font-size=\"22\" font-weight=\"600\" x=\"205\" y=\"412\">Update request</text><rect fill=\"#214e48\" height=\"29\" rx=\"14\" width=\"174\" x=\"205\" y=\"432\"></rect><circle cx=\"221\" cy=\"447\" fill=\"#65dec0\" r=\"4\"></circle><text fill=\"#c7f3e5\" font-size=\"14\" x=\"234\" y=\"452\">Agreed next steps</text><rect fill=\"#122029\" height=\"62\" rx=\"10\" stroke=\"#3c6170\" width=\"333\" x=\"205\" y=\"480\"></rect><text fill=\"#b8d0dc\" font-size=\"15\" x=\"221\" y=\"504\">Page content</text><path d=\"M221 523h222\" stroke=\"#6e91a5\" stroke-linecap=\"round\" stroke-width=\"4\"></path><path d=\"M208 571h174M208 590h119\" stroke=\"#8aaebc\" stroke-linecap=\"round\" stroke-width=\"4\"></path><rect fill=\"#58d5e3\" height=\"35\" rx=\"10\" width=\"111\" x=\"426\" y=\"564\"></rect><text fill=\"#10252b\" font-size=\"15\" font-weight=\"600\" x=\"451\" y=\"587\">Review</text></g><g><rect fill=\"#263e4e\" height=\"170\" rx=\"16\" stroke=\"#8098b5\" width=\"132\" x=\"44\" y=\"474\"></rect><rect fill=\"#1a2d3a\" height=\"45\" rx=\"8\" stroke=\"#a1b9d8\" width=\"49\" x=\"76\" y=\"496\"></rect><path d=\"M76 508h49M87 491v10M113 491v10\" stroke=\"#91b4ef\" stroke-width=\"2\"></path><g fill=\"#91b4ef\"><rect height=\"6\" rx=\"2\" width=\"6\" x=\"87\" y=\"518\"></rect><rect height=\"6\" rx=\"2\" width=\"6\" x=\"101\" y=\"518\"></rect></g><text fill=\"#e2edf4\" font-size=\"16\" x=\"75\" y=\"567\">Support</text><text fill=\"#e2edf4\" font-size=\"16\" x=\"75\" y=\"589\">window</text><text fill=\"#b9ccdd\" font-size=\"14\" x=\"75\" y=\"619\">By package</text></g></svg></div>\n</div>\n</section>\n\n<section aria-labelledby=\"membership-title\" class=\"l-sec\" data-8b-section=\"membership\" id=\"membership\"><div class=\"mb-slide m-slide\">\n<div class=\"mb-head\"><h2 class=\"m-text-3\" data-8b-motion=\"streak\" id=\"membership-title\">Website <span class=\"brand-word brand-word-paper\">packages.</span></h2><p class=\"m-text-5\">Choose the scope that fits your business. Start with a free consultation and get a quote for your project.</p></div>\n<p class=\"mb-shared m-text\">Every package includes custom design, a mobile-responsive build, contact options and SEO foundations.</p>\n<div class=\"mb-plans\" data-8b-motion=\"rise\"><article class=\"mb-plan\">\n<h3 class=\"m-text-6\">Foundation</h3><p class=\"mb-for m-text\">A focused custom website for a business establishing or replacing a basic online presence.</p>\n<ul class=\"mb-inc\"><li class=\"m-text\">Up to 3 pages</li><li class=\"m-text\">1 revision round</li><li class=\"m-text\">30 days of post-launch support</li></ul>\n<a class=\"m-btn\" href=\"/contact?package=foundation\" aria-label=\"Request a free quote for Foundation\"><span class=\"m-btn__label\">Request a free quote</span></a></article><article class=\"mb-plan mb-plan--featured\"><span class=\"hd-best-value\">Recommended</span>\n<h3 class=\"m-text-6\">Starter</h3><p class=\"mb-for m-text\">A larger custom website for a growing business with more services or content.</p>\n<ul class=\"mb-inc\"><li class=\"m-text\">Up to 5–6 pages</li><li class=\"m-text\">Content management</li><li class=\"m-text\">Google Analytics setup</li><li class=\"m-text\">2 revision rounds</li><li class=\"m-text\">45 days of post-launch support</li></ul>\n<a class=\"m-btn-2\" href=\"/contact?package=starter\" aria-label=\"Request a free quote for Starter\"><span class=\"m-btn__label\">Request a free quote</span></a></article><article class=\"mb-plan\">\n<h3 class=\"m-text-6\">Growth</h3><p class=\"mb-for m-text\">A more extensive website for businesses with deeper content, service lines or integrations.</p>\n<ul class=\"mb-inc\"><li class=\"m-text\">Up to 10–12 pages</li><li class=\"m-text\">Content management</li><li class=\"m-text\">Google Analytics and Google Business Profile setup</li><li class=\"m-text\">2 revision rounds</li><li class=\"m-text\">60 days of post-launch support</li></ul>\n<a class=\"m-btn\" href=\"/contact?package=growth\" aria-label=\"Request a free quote for Growth\"><span class=\"m-btn__label\">Request a free quote</span></a></article></div><a class=\"m-link mb-compare\" href=\"/pricing\">Compare all package features</a></div></section>\n\n<section aria-labelledby=\"faq-title\" class=\"l-sec\" data-8b-section=\"faq\" id=\"faq\">\n<div class=\"fq-slide m-slide-3\">\n<div class=\"fq-head\">\n<h2 class=\"m-text-3\" id=\"faq-title\">A few useful <span class=\"brand-word\">answers.</span></h2>\n<p class=\"m-text\">Still unsure? Send us a message. We will help you work out which option makes sense.</p>\n</div>\n<div class=\"fq-body\">\n<div aria-hidden=\"true\" class=\"fq-rail\"><span class=\"fq-ball m-orb\"></span></div>\n<div class=\"fq-list\">\n<details class=\"fq-item\"><summary class=\"m-text-6\">What kind of websites do you build?</summary><p class=\"m-text\">Custom business websites and redesigns focused on clear information, responsive use, performance and straightforward enquiry paths.</p></details>\n<details class=\"fq-item\"><summary class=\"m-text-6\">Can you add payments or bookings?</summary><p class=\"m-text\">Payment, booking and enquiry integrations can be scoped when the required provider supports the business and the necessary account access is available.</p></details>\n<details class=\"fq-item\"><summary class=\"m-text-6\">What is a typical timeline?</summary><p class=\"m-text\">Many standard projects take around 3 to 6 weeks. The proposal confirms the estimate for your scope.</p></details>\n<details class=\"fq-item\"><summary class=\"m-text-6\">Can I update the website myself?</summary><p class=\"m-text\">Content management is included in Starter and Growth for agreed fields, can be added to Foundation, and can be scoped for Custom projects.</p></details>\n<details class=\"fq-item\"><summary class=\"m-text-6\">What support is provided after launch?</summary><p class=\"m-text\">Foundation includes 30 days, Starter 45 days and Growth 60 days of post-launch support. Custom support is defined in the proposal.</p></details>\n<details class=\"fq-item\"><summary class=\"m-text-6\">Do I own the website?</summary><p class=\"m-text\">The final approved website files and assets transfer as agreed when the project closes. The domain remains in your registrar account.</p></details>\n</div>\n</div>\n</div>\n</section>\n\n<section aria-labelledby=\"contact-title\" class=\"l-sec\" data-8b-section=\"contact\" id=\"contact\">\n<div class=\"ct-slide m-slide\">\n<div class=\"ct-run\">\n<h2 class=\"ct-title m-text-3\" id=\"contact-title\">Tell us what you <span class=\"brand-word\">need.</span></h2>\n<div aria-hidden=\"true\" class=\"ct-line\"></div>\n</div>\n<div class=\"ct-grid\">\n<dl class=\"ct-info\">\n<div><dt class=\"m-text-4\">Based in</dt><dd class=\"m-text-6\">Mahé, Seychelles</dd></div>\n<div><dt class=\"m-text-4\">Let’s talk</dt><dd class=\"m-text\">We aim to reply within 24 hours.</dd></div>\n<div><dt class=\"m-text-4\">Phone</dt><dd><a class=\"m-link\" href=\"tel:+2482604525\">+248 2604525</a></dd></div>\n<div><dt class=\"m-text-4\">Email</dt><dd><a class=\"m-link\" href=\"mailto:horizondigital.sey@gmail.com\">horizondigital.sey@gmail.com</a></dd></div>\n</dl>\n<div class=\"ct-form hd-contact-actions\" data-8b-motion=\"rise\"><h3 class=\"m-text-6\">Start with a conversation.</h3><p class=\"m-text\">Tell us about your business, what you have in mind and where you would like help.</p><a class=\"m-btn\" href=\"/contact\"><span class=\"m-btn__label\">Request a free quote</span></a><a class=\"m-link\" href=\"https://wa.me/2482604525?text=Hi+Horizon+Digital%2C+I%27d+like+to+discuss+a+website+project.\">Message us on WhatsApp</a></div>\n</div>\n</div>\n</section>\n";
export const editorialHomeFaq = [{"question":"What kind of websites do you build?","answer":"Custom business websites and redesigns focused on clear information, responsive use, performance and straightforward enquiry paths."},{"question":"Can you add payments or bookings?","answer":"Payment, booking and enquiry integrations can be scoped when the required provider supports the business and the necessary account access is available."},{"question":"What is a typical timeline?","answer":"Many standard projects take around 3 to 6 weeks. The proposal confirms the estimate for your scope."},{"question":"Can I update the website myself?","answer":"Content management is included in Starter and Growth for agreed fields, can be added to Foundation, and can be scoped for Custom projects."},{"question":"What support is provided after launch?","answer":"Foundation includes 30 days, Starter 45 days and Growth 60 days of post-launch support. Custom support is defined in the proposal."},{"question":"Do I own the website?","answer":"The final approved website files and assets transfer as agreed when the project closes. The domain remains in your registrar account."}];
